// Gate 7 · Banned identifiers
//
// D-05: roughly 620 internal identifiers may appear only inside a downloadable
// bundle, where they are filenames, and never in rendered HTML. The strongest
// argument for the ban is not that the identifiers are opaque. It is that they
// collide: E1-E6 are simultaneously errata numbers and the estimator series,
// R1-R4 are predictions while R1-R15 are design rules and a third R1-R8 are
// statistical review items. A reader who learns the scheme still cannot decode
// it.
//
// The list is GENERATED by P1 into src/data/banned-terms.json, from the
// registries. It is not hand-written here, and this gate refuses to invent one:
// a hand-written ban list is a list of the identifiers somebody remembered.
//
// Four terms survive and are never flagged: the kernel, the sciences, the
// gates, the wedge.
//
// Usage:  node scripts/checks/banned.mjs [dist] [--record]

import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { DIST, ROOT, distPages, routeOf, textNodes, skip, recordVacuity } from "./_lib.mjs";
import { checkRatchet, writeRatchet } from "./_ratchet.mjs";

const RECORD = process.argv.includes("--record");
const dist = process.argv[2]?.startsWith("--") ? DIST : (process.argv[2] ?? DIST);
// P1 generates this. BANNED_TERMS points it at a fixture so the gate can be
// demonstrated failing before P1 lands, without writing into P1's directory.
const TERMS = process.env.BANNED_TERMS ?? join(ROOT, "src", "data", "banned-terms.json");

if (!existsSync(TERMS)) {
  skip(
    7,
    `src/data/banned-terms.json does not exist. Packet P1 generates it from the registries (D-05, ~620 strings across 14 families). This gate will not hand-write a substitute: a hand-written ban list is a list of the identifiers somebody remembered.`,
  );
}

const raw = JSON.parse(readFileSync(TERMS, "utf-8"));
const terms = Array.isArray(raw) ? raw : (raw.terms ?? Object.keys(raw));

// ---------------------------------------------------------------------------
// The family map, and why the allowance below reads it rather than the spelling
// ---------------------------------------------------------------------------
//
// banned-terms.json groups all 399 identifiers into eleven families. That map is
// the only thing that knows `S13` is a science and `E19` is an erratum, because
// nothing about the two strings tells them apart: both are a capital letter and
// a number. An allowance written as a regex over the shape (`/^[STEFACD]\d+$/`
// or anything like it) would permit `E19` because it looks like `E12` looks
// like `A1`, and permitting errata by accident is the exact leak the /docs/
// allowance is scoped to avoid. So the family is looked up, never inferred.
const familiesById = new Map();
const familyTable = (!Array.isArray(raw) && raw.families) || null;
for (const [family, list] of Object.entries(familyTable ?? {})) {
  for (const t of list ?? []) {
    if (!familiesById.has(t)) familiesById.set(t, new Set());
    familiesById.get(t).add(family);
  }
}

// The three families reward_lens 3.0.0 publishes as user-facing names.
//
//   science     the shipped study module paths: `studies/s06_topology/`, and
//               the `S6` the registry and the CLI both print for it
//   theorem     the theorem registry, which /docs/sciences/ renders as a table
//   instrument  the observable codes printed beside the classes in the API
//               reference: `KUI(...)` is documented as `A1`, and
//               `reward_lens.measure.indices.heritability` is documented as `C2`
//
// A reader of /docs/ needs these to use the package: they are what a user types
// and what the library prints back. Every other family stays banned everywhere,
// including under /docs/, because the rest of the site, and the rest of the
// docs, speaks to people who have not read the library reference.
const PUBLISHED_FAMILIES = new Set(["science", "theorem", "instrument"]);

/**
 * True when the family map settles that this spelling is published vocabulary.
 *
 * TWO REFUSALS, BOTH DELIBERATE.
 *
 * A term with no family is not permitted. The map is the authority, and a term
 * the map does not describe is a term nobody has classified; treating that as a
 * pass would make every future identifier permitted under /docs/ until somebody
 * remembered to add it, which is a ban list that grows holes as it grows.
 *
 * A term whose families STRADDLE the published set and the banned set is not
 * permitted either. `E1` through `E6` are simultaneously errata and the E-series
 * instruments, the collision the header of this file opens with. For those six
 * spellings the family map does not settle the question, and the whole reason to
 * key on family rather than shape is that the allowance only fires where the
 * question is settled. So `E3` under /docs/ fails, and it should: a reader
 * meeting it cannot tell which `E3` it is any more than the gate can.
 */
function isPublishedVocabulary(term) {
  const fams = familiesById.get(term);
  if (!fams || fams.size === 0) return false;
  for (const f of fams) if (!PUBLISHED_FAMILIES.has(f)) return false;
  return true;
}

// D-05: the exemptions are the campaign log, where the identifiers are the
// record's own field values, and downloadable bundles, where they are
// filenames.
const EXEMPT_ROUTES = ["/log/", "/specs/", "/demos/"];
const EXEMPT_EXT = [".json", ".zip", ".tar.gz", ".ipynb", ".csv"];

// C-56 · D-40: the evidence RECORD may carry the store's own keys, and the
// evidence INDEX may not.
//
// D-40 ruled this in August and gate 6 implements it (terms.json, every rule's
// `allow.routePatterns`). Gate 7 never got the same clause, so all 27 record
// pages have been failing this gate on `H-avp`, `K-err`, `ADJ-AVP` and their
// siblings, which are the record's own `outcomes` keys and the reason the route
// exists: a reader arrives there having followed a number down from a finding,
// and a record that renamed its own observable can no longer be checked against
// the store.
//
// THE ALLOWANCE IS A PATTERN, NOT A PREFIX, AND THAT IS THE WHOLE POINT.
// `/evidence/` is a browsable surface reachable from the navigation, and a
// prefix exemption would hand it the record's allowance by proximity, which is
// the failure D-40's correction of 2026-08-08 records. The pattern is anchored
// at both ends against a 32-hex id, so:
//
//   /evidence/                             swept
//   /evidence/a34457e8.../                 exempt
//   /evidence/a34457e8.../anything/        swept
//   /evidence/not-a-hex-id/                swept
//
// Store ids on this site are 32 hex characters (`bareId` of `ev:<md5>`); the
// length is fixed here rather than left open so a shorter slug that happens to
// be hex cannot inherit the exemption.
const EXEMPT_ROUTE_PATTERNS = [/^\/evidence\/[0-9a-f]{32}\/$/];

// ---------------------------------------------------------------------------
// One term whose SPELLING collides with something that is not an identifier
// ---------------------------------------------------------------------------
//
// `R2` is two things. In the generated registry it is one of the four
// predictions, R1 to R4, and D-05 bans it. In `/see/run/` it is the row label
// of a coefficient of determination, inside the run bundle's expected output:
//
//     transition midpoint    106.9368    106.0000
//     10-to-90 width          23.9823     23.9000
//     R2                      0.99555     0.99600
//
// That is R², ASCII-folded because the block is the literal stdout of a
// reproduce script. It is not an identifier and no reader can mistake it for
// one.
//
// WHY NOT JUST DROP `R2` FROM THE REGISTRY. Because then prediction R2 walks
// onto every other page in the site unchallenged, and the ban list is generated
// from the registries precisely so that nobody gets to decide by hand which
// identifiers are worth catching. Deleting the term to silence one page is the
// weakening this file exists to prevent.
//
// SO THE ALLOWANCE IS SHAPED, NOT NAMED, and it is as narrow as the collision:
//
//   1. the match is inside a <pre> or <code>, machine output rather than prose,
//      and
//   2. it begins its line, with a number as the next thing on that line.
//
// Both must hold. `R2 was refuted` in prose fails. `R2` in a code block next to
// a word fails. `R2` at the start of a line followed by a number, in running
// text outside a verbatim block, fails. Only a labelled row in a fixed-width
// numeric table is permitted, which is the one shape the statistic takes and a
// shape no sentence takes.
//
// The other three predictions get no allowance: R1, R3 and R4 collide with
// nothing. An allowance per collision, not per family.
//
// This is why the sweep reads textNodes() rather than visibleText(): a rule
// about the difference between a table and a sentence needs to know which
// element the match sits in. The two produce the same hits — 207, over the 152
// swept pages of the build this was written against, checked term by term and
// route by route before the switch — so the change costs no coverage. If they
// ever diverge, textNodes is the finer of the two: it decodes entities, so an
// identifier hidden as `&#82;2` is caught here and was not before.
//
// ---------------------------------------------------------------------------
// One ROUTE where a whole class of identifier is the package's own vocabulary
// ---------------------------------------------------------------------------
//
// /docs/ documents reward_lens 3.0.0, and that library publishes its science,
// theorem and instrument codes as names a user types and reads back. Checked
// against the shipped source rather than inferred from the site:
//
//   - reward-lens-clean/src ships the study modules `s02_gauge`, `s03_thermo`,
//     `s06_topology` and eleven more. The science id IS the import path.
//   - /docs/api/measure/ renders `KUI(properties=..., null_draws=10000, seed=0)`
//     and immediately under it `A1 Knowledge-Utilization Index`. `A1` is the
//     published code for that observable, printed beside its class.
//   - /docs/instruments/heritability/ renders
//     `reward_lens.measure.indices.heritability is C2`.
//   - /docs/sciences/ renders the theorem registry itself, `T11` and `T12` and
//     their statements, as a table.
//
// A reader who cannot resolve `C2` cannot use `heritability`. That is the
// opposite of D-05's complaint, which is about identifiers a reader has no way
// to decode; these decode on the page that prints them, and in `help()`.
//
// THE ALLOWANCE IS ROUTE-SCOPED AND FAMILY-VERIFIED, AND IT IS BOTH OR NEITHER.
//
//   route      /docs/ only. The same string on /atlas/, /log/'s neighbours, the
//              homepage or an essay fails exactly as before, because those pages
//              are read by people who have not opened the library reference.
//   family     `science`, `theorem` or `instrument`, read off the generated map
//              above. Not the shape of the string.
//
// This is the same principle already recorded for `ADJUDICATED`, which gate 6
// permits under /docs/api/ because it is a real member of the library's
// `TrustLevel` enum: preserve exact API identifiers, because renaming one in the
// reference makes the reference wrong for anyone typing it.
//
// WHAT IT DELIBERATELY DOES NOT COVER. `errata`, `campaign card`, `hypothesis`,
// `kill criterion`, `prediction`, `work package`, `experiment` and
// `project codename` stay banned under /docs/ like everywhere else. Those are
// internal bookkeeping: no reader can resolve `E19` or `ADJ-AVP`, and the
// library does not publish them as names. Nine such hits on /docs/ prose were
// rewritten into what they refer to rather than covered here; the nine that
// remain are on the ratchet below, with the upstream file that owns each.
const CONTEXT_ALLOWANCES = [
  {
    term: "R2",
    name: "R2 as a coefficient of determination, labelling a row of numbers",
    permits({ text, index, term, ancestors }) {
      if (!ancestors.some((a) => a.tag === "pre" || a.tag === "code")) return false;
      const lineStart = text.lastIndexOf("\n", index - 1) + 1;
      if (!/^[ \t]*$/.test(text.slice(lineStart, index))) return false;
      return /^[ \t]+[-+]?(\d|\.\d)/.test(text.slice(index + term.length));
    },
  },
  {
    matches: isPublishedVocabulary,
    name: "reward_lens 3.0.0's published science, theorem and instrument codes, under /docs/",
    permits: ({ route }) => route.startsWith("/docs/"),
  },
];

// The allowance's authority is the family map. Without one it permits nothing,
// which is the safe direction, but it must not do that quietly: a generator that
// stopped emitting `families` would otherwise read as 111 new violations with no
// hint of the cause.
if (!familyTable || Object.keys(familyTable).length === 0) {
  console.error(
    `NOTE banned: ${TERMS} carries no "families" map, so the /docs/ published-vocabulary ` +
      `allowance is inert on this run and every identifier is held to the ban. The family map ` +
      `is that allowance's only authority; there is nothing to verify a term against without it.`,
  );
}

const pages = distPages(dist);
if (pages.length === 0) {
  console.error(`FAIL banned: no built pages under ${dist}. Run npm run build first.`);
  process.exit(1);
}

// Word-boundary match on each term, longest first so `H-avp` is reported rather
// than the `H-a` prefix of something else.
const sorted = [...new Set(terms)].filter(Boolean).sort((a, b) => b.length - a.length);
const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const RE = new RegExp(`(?<![\\w-])(${sorted.map(escape).join("|")})(?![\\w-])`, "g");

let failures = 0;
const byTerm = new Map();
let swept = 0;
// Counted rather than assumed. An exemption that silently covers more routes
// than it was written for is the shape five gates in this repository have
// already failed in, so the count is printed on every run and a pattern that
// matches nothing says so.
const exemptedBy = new Map([
  ...EXEMPT_ROUTES.map((p) => [p, 0]),
  ...EXEMPT_ROUTE_PATTERNS.map((re) => [String(re), 0]),
]);
// Same property, one level down: a context allowance counts the hits it
// covered and the routes they were on, and says so when that count is zero.
const allowedBy = new Map(CONTEXT_ALLOWANCES.map((a) => [a.name, { hits: 0, routes: new Set() }]));

for (const file of pages) {
  const route = routeOf(file, dist);
  const prefix = EXEMPT_ROUTES.find((p) => route.startsWith(p));
  if (prefix) {
    exemptedBy.set(prefix, exemptedBy.get(prefix) + 1);
    continue;
  }
  const pattern = EXEMPT_ROUTE_PATTERNS.find((re) => re.test(route));
  if (pattern) {
    exemptedBy.set(String(pattern), exemptedBy.get(String(pattern)) + 1);
    continue;
  }
  if (EXEMPT_EXT.some((e) => route.endsWith(e))) continue;
  swept += 1;

  for (const node of textNodes(readFileSync(file, "utf-8"))) {
    for (const m of node.text.matchAll(RE)) {
      const key = m[1];
      const allowance = CONTEXT_ALLOWANCES.find(
        (a) =>
          (a.term !== undefined ? a.term === key : a.matches(key)) &&
          a.permits({
            text: node.text,
            index: m.index,
            term: key,
            ancestors: node.ancestors,
            route,
          }),
      );
      if (allowance) {
        const seen = allowedBy.get(allowance.name);
        seen.hits += 1;
        seen.routes.add(route);
        continue;
      }
      failures += 1;
      if (!byTerm.has(key)) byTerm.set(key, new Set());
      byTerm.get(key).add(route);
    }
  }
}

// ---------------------------------------------------------------------------
// The residue, and why it is a ratchet rather than a wider allowance
// ---------------------------------------------------------------------------
//
// Nine hits survive the allowance above, all on /docs/api/, all of them errata
// or prediction ids: E12, E15, E16, E17, E18, E19, R3, R4. They are NOT ported
// site prose and no edit to this repository can honestly remove them. /docs/api/
// is generated by scripts/build_api_ref.py, which runs griffe over the shipped
// library and renders its docstrings verbatim, so
//
//     Per-axis reward signal-to-noise ratio (E16).
//
// on /docs/api/measure/ is the first line of `PromptSNR.__doc__` in
// reward-lens-clean/src/reward_lens/measure/battery/snr.py, and it is what
// `help(PromptSNR)` prints for anyone who installed the package. Rewriting the
// site's copy would make the reference disagree with the library and would be
// reverted by the next generator run. C-10 is the standing rule and gates 5 and
// 9 already carry it at this exact route: the site does not silently correct the
// prose of a page it ports.
//
// So the identifiers are a real defect, D-05 is right about them, and the fix
// belongs upstream in reward_lens rather than here. That is precisely what a
// ratchet is for, and the site already has the idiom (gate 14's and gate 15's).
// The difference from an allowance is the point:
//
//   an allowance   permits the CLASS, forever, and a docstring that gains an
//                  `(E20)` tomorrow ships unnoticed
//   the ratchet    permits these NINE, names the upstream file that owns each,
//                  fails on a tenth, and prints every entry that has been fixed
//                  so the list can only shrink
//
// Re-record after an upstream release lands:  node scripts/checks/banned.mjs --record
const RATCHET = join(ROOT, "scripts", "checks", "ratchet-banned.txt");
const RATCHET_HEADER = `# Gate 7's ratchet: banned identifiers in rendered output that this repository cannot fix.
#
# One line per hit: owning packet | date recorded | upstream source | route | identifier.
#
# Every entry is on /docs/api/, which scripts/build_api_ref.py generates by
# running griffe over the shipped reward_lens source and rendering its docstrings
# verbatim. The identifiers below are the LIBRARY's, in the library's own
# docstrings, and they are what help() prints for anyone who pip-installed it.
# Editing the site's copy would make the API reference disagree with the package
# and would be undone by the next generator run. C-10, which gates 5 and 9 both
# carry at this same route: the site does not silently correct the prose of a
# page it ports.
#
# They are still defects. D-05 is right that a reader cannot resolve "(E16)".
# The fix is a docstring change in reward-lens/reward-lens, and each line below
# names the file to change.
#
# THIS LIST MAY SHRINK AND MUST NOT GROW. A hit that is not here fails the build.
# It is a ratchet and not an allow-list: an allow-list would also swallow the
# (E20) that the next release's docstrings introduce.
#
# Re-record after an upstream release lands:  node scripts/checks/banned.mjs --record`;

// route | identifier, one per hit pair, so a term that moves page reads as the
// new hit it is rather than hiding inside an existing entry's count.
const observed = [];
for (const [term, routes] of byTerm) for (const r of routes) observed.push(`${r} | ${term}`);

// Only the canonical dist is measured against the site's ratchet. The gate takes
// a dist as argv[2] and its own regression test hands it a five-page temporary
// one; comparing a fixture's hits to the site's recorded debt is the same
// category error that had recordVacuity filing fixture numbers as the site's,
// documented at the foot of this file. A fixture run keeps the old behaviour:
// every hit fails.
const ratcheted = dist === DIST && existsSync(RATCHET);

if (RECORD) {
  const n = writeRatchet(RATCHET, observed, {
    header: RATCHET_HEADER,
    packet: "qual/docs-vocab",
    source: "reward_lens docstring",
  });
  console.log(`banned: recorded ${n} hit(s) to ${RATCHET}`);
  process.exit(0);
}

let newFindings = observed;
let ratchetSize = 0;
if (ratcheted) {
  const result = checkRatchet(RATCHET, observed, {
    name: "banned",
    howToFix:
      "An identifier this repository owns must be rewritten into what it refers to. " +
      "One it does not own, a reward_lens docstring rendered verbatim under /docs/api/, " +
      "is fixed upstream and recorded here with the file that owns it.",
  });
  // Only the CLOSED half is printed from the ratchet's own lines. The new
  // findings are reported below in this gate's own format, so a violation reads
  // identically whether or not a ratchet file happens to exist.
  for (const line of result.lines) if (!line.startsWith("  NEW ")) console.error(line);
  newFindings = result.added;
  ratchetSize = result.size;
}

const newByTerm = new Map();
for (const sig of newFindings) {
  const [route, term] = sig.split(" | ");
  if (!newByTerm.has(term)) newByTerm.set(term, new Set());
  newByTerm.get(term).add(route);
}
for (const [term, routes] of [...newByTerm].sort((a, b) => b[1].size - a[1].size)) {
  const list = [...routes].slice(0, 5).join(", ");
  console.error(
    `FAIL banned identifier "${term}" on ${routes.size} route(s): ${list}${routes.size > 5 ? " ..." : ""}`,
  );
}

const exemptionReport = [...exemptedBy]
  .map(([what, n]) => `${what}=${n}`)
  .join(", ");

/**
 * A FIXTURE MUST NOT WRITE THE SITE'S LEDGER.
 *
 * `recordVacuity` writes reports/vacuous-gates.json, which is keyed by gate
 * number and lives beside the repository rather than beside the dist that was
 * scanned. This gate takes a dist as `argv[2]`, and tests/regression/
 * banned-gate.test.mjs runs it against a five-page temporary one. So
 * `node --test tests/regression/banned-gate.test.mjs` was overwriting gate 7's
 * recorded vacuity with the fixture's numbers, and the entry committed on
 * build/scene-core says "2 of 5 pages were not swept ... /log/=1" — a
 * measurement of a fixture, filed as a measurement of the site, in the one file
 * a reader is told to check before believing a green run.
 *
 * Every gate that accepts a dist argument and calls recordVacuity has this.
 * Fixed here because this file is the packet's; the general fix belongs in
 * _lib.mjs, whose owner is told.
 */
if (pages.length !== swept && dist === DIST) {
  recordVacuity(
    7,
    `${pages.length - swept} of ${pages.length} pages were not swept: they are under an exempt prefix (${EXEMPT_ROUTES.join(", ")}) or match the D-40 evidence-record pattern, where D-05 and D-40 permit the identifiers. Per allowance: ${exemptionReport}.`,
  );
}

// A pattern that matches nothing is a pattern nobody has shown to work. It does
// not fail the build, because a site could legitimately ship without records,
// but it is stated so that a rename cannot silently retire the allowance and
// leave 27 routes failing again.
for (const [what, n] of exemptedBy) {
  if (n === 0) {
    console.error(
      `NOTE banned: the allowance ${what} matched 0 of ${pages.length} built routes on this run.`,
    );
  }
}
for (const [name, { hits }] of allowedBy) {
  if (hits === 0) {
    console.error(
      `NOTE banned: the context allowance "${name}" covered 0 hits on this run. ` +
        `Either the collision it was written for is gone, or it stopped matching.`,
    );
  }
}

console.log(
  `\nbanned: ${sorted.length} terms, ${swept} of ${pages.length} pages swept, ${byTerm.size} distinct terms found, ${failures} hits`,
);
console.log(`banned: allowances applied: ${exemptionReport}`);
for (const [name, { hits, routes }] of allowedBy) {
  console.log(
    `banned: context allowance "${name}" covered ${hits} hit(s) on ${routes.size} route(s)` +
      (routes.size ? `: ${[...routes].slice(0, 5).join(", ")}` : ""),
  );
}
if (ratcheted) {
  console.log(
    `banned: ${ratchetSize} hit(s) on the ratchet ${RATCHET}, ${newFindings.length} not on it`,
  );
}
process.exit(newFindings.length > 0 ? 1 : 0);
